/* botroom-overlay-20261023b (Dan 3:10 PM): Bot Room full screen inside HubFace. No X. Esc or the Hub Rooms Bot Room button minimizes to a small dock badge (iframe stays loaded, hidden). Badge or button restores. Status dot: green = running, blinking red = stopped (paused / human sign-off / Observer queue). Read from same-origin iframe DOM; window.botroomStatus('running'|'stopped'|null) overrides. Iframe gets ?demo=1&viewer= from dashboard ?brdemo=1&brviewer=. Roll back: point the script tag back at botroom-overlay-20261023a.js. */
(function(){var o=null,f=null,d=null,dot=null,ov=null,st='running';
function css(){var s=document.createElement('style');s.textContent='@keyframes brBlink{0%,49%{opacity:1}50%,100%{opacity:.15}}#brBotDock{position:fixed;left:14px;bottom:14px;z-index:2147483000;width:44px;height:44px;border-radius:50%;border:2px solid #fff;background:#0b1f4a;color:#fff;font:0/40px system-ui,sans-serif;text-align:center;cursor:pointer;box-shadow:0 2px 10px rgba(0,0,0,.5);display:none;padding:0}#brBotDock .brGl{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%)}#brBotDock .brDot{box-sizing:border-box;position:absolute;right:-3px;top:50%;margin-top:-7px;width:14px;height:14px;border-radius:50%;border:2px solid #fff;background:#16c060}#brBotDock.stopped .brDot{background:#e5202b;animation:brBlink 1s steps(1) infinite}#brToast{position:fixed;left:50%;bottom:30px;transform:translateX(-50%);z-index:2147483001;background:#0b1f4a;color:#fff;font:600 13px system-ui,sans-serif;padding:6px 12px;border-radius:14px;opacity:1;transition:opacity .6s;pointer-events:none}';document.head.appendChild(s);}
function full(){return o&&o.style.display!=='none';}
function toast(){var t=document.createElement('div');t.id='brToast';t.textContent='Esc to exit';document.body.appendChild(t);setTimeout(function(){t.style.opacity='0';},1200);setTimeout(function(){t.remove();},1900);}
function show(){o.style.display='block';d.style.display='none';toast();try{f.focus();}catch(e){}}
function minimize(){if(!o)return;o.style.display='none';d.style.display='block';}
function esc(e){if(e.key==='Escape'&&full()){e.preventDefault();minimize();}}
function build(){css();o=document.createElement('div');o.id='brOverlay';
 o.style.cssText='position:fixed;left:0;top:0;width:100vw;height:100vh;z-index:2147483000;background:#000;display:none';
 f=document.createElement('iframe');var q=new URLSearchParams(location.search),qs=[];if(q.get('brdemo')==='1')qs.push('demo=1');if(q.get('brviewer'))qs.push('viewer='+encodeURIComponent(q.get('brviewer')));if(q.get('brlive'))qs.push('live='+encodeURIComponent(q.get('brlive')));var hw=new URLSearchParams(location.hash.slice(1)).get('brw');if(hw)history.replaceState(null,'',location.pathname+location.search);f.src='/botroom/'+(qs.length?'?'+qs.join('&'):'')+(hw?'#w='+encodeURIComponent(hw):'');   /* brlive-20261023a: ?brlive=<relay room>#brw=<owner watch token> -> Bot Room live view */f.title='Bot Room';f.style.cssText='border:0;width:100%;height:100%;display:block';
 f.addEventListener('load',function(){try{f.contentWindow.addEventListener('keydown',esc,true);}catch(e){}});
 o.appendChild(f);var mn=document.createElement('button');mn.type='button';mn.id='brMinBtn';mn.title='Minimize Bot Room (Esc)';mn.setAttribute('aria-label','Minimize Bot Room');
 mn.innerHTML='<svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3l6 6M9 4v5H4M21 3l-6 6M15 4v5h5M3 21l6-6M4 15h5v5M21 21l-6-6M20 15h-5v5"/></svg>';
 mn.style.cssText='position:absolute;top:8px;right:120px;z-index:2;width:32px;height:32px;padding:0;display:flex;align-items:center;justify-content:center;border:2px solid rgba(255,255,255,.6);border-radius:8px;background:#0b1f4a;color:#fff;cursor:pointer';
 mn.onclick=minimize;o.appendChild(mn);document.body.appendChild(o);/* brmin-20261023a: corner minimize (not a close X), sits right of the header buttons */
 d=document.createElement('button');d.type='button';d.id='brBotDock';d.title='Bot Room';d.setAttribute('aria-label','Bot Room');d.innerHTML='<svg class="brGl" viewBox="0 0 24 24" width="62%" height="62%" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 6V2.4" stroke-width="1.4"/><path d="M14.2 6c-1.4-.4 1.2-.9-.1-1.3s1.1-.8-.2-1.2S12.6 2.7 12 2.4" stroke-width="1"/><circle class="brAnt" cx="12" cy="2.4" r="1.9" stroke="#fff" stroke-width=".8"/><rect x="5" y="6" width="14" height="12" rx="3"/><circle cx="9.3" cy="11.3" r="1.4" fill="currentColor"/><circle cx="14.7" cy="11.3" r="1.4" fill="currentColor"/><path d="M9.5 15h5M3 11v3M21 11v3"/></svg><span class="brDot"></span>';d.onclick=show;document.body.appendChild(d);dot=d;brSize();window.addEventListener('resize',brSize);setTimeout(brSize,1500);
 setInterval(poll,1000);}
function poll(){var s='running';if(ov)s=ov;else{try{var w=f.contentWindow,S=w.__brStatus;if(S){s=(S.status==='stopped'&&S.viewer!=='opposing')?'stopped':'running';}else{var b=w.document,q=b.getElementById('oqn');
 if(b.body.classList.contains('paused')||b.querySelector('#stages .stg.wait')||(q&&parseInt(q.textContent,10)>0))s='stopped';}}catch(e){}}
 st=s;dot.classList.toggle('stopped',s==='stopped');dot.title='Bot Room \u2014 '+(s==='stopped'?'stopped, needs you':'negotiation running');}
window.botroomStatus=function(s){ov=(s==='running'||s==='stopped')?s:null;if(o)poll();return st;};
window.__brOpen=function(){if(!o)build();if(full())minimize();else show();return true;};
window.addEventListener('keydown',esc,true);/* brmin-20261023b: capture phase so dashboard Esc handlers can't swallow it */
})();

/* dockfit-20261023c: dock matches the dashboard's own widget icon buttons (#btnFs) exactly; glyph = dashboard OUT4 four outward arrows in every state */
function brSize(){var d=document.getElementById('brBotDock');if(!d)return;var r=document.getElementById('btnFs'),w=0,h=0;if(r){var b=r.getBoundingClientRect();w=b.width;h=b.height;}if(!w||!h){var cs=r&&getComputedStyle(r);w=h=0;}var z=Math.round(Math.max(w,h)*100)/100||38;d.style.width=z+'px';d.style.height=z+'px';var g=d.querySelector('.brGl');if(g){g.style.width=g.style.height=(z*0.62)+'px';}var t=d.querySelector('.brDot');if(t){var k=Math.round(z*0.3);t.style.width=t.style.height=k+'px';t.style.marginTop=(-k/2)+'px';t.style.right=(-k*0.25)+'px';}}

/* minrow-20261023a: minimize sits on the Observe row, immediately left of it; inward four-arrow glyph */
function brMinPos(){var mn=document.getElementById('brMinBtn'),f=document.querySelector('#brOverlay iframe');if(!mn||!f)return;try{var dc=f.contentWindow.document,b=dc.getElementById('obsBtn');if(!b)return;
 var row=b.parentElement;if(row&&!row.dataset.brMinPad){row.dataset.brMinPad='1';var cs=f.contentWindow.getComputedStyle(row);row.style.paddingRight=(parseFloat(cs.paddingRight)||0)+44+'px';}
 var r=b.getBoundingClientRect();if(!r.width)return;mn.style.top=Math.round(r.top+r.height/2-16)+'px';mn.style.right='8px';}catch(e){}}
/* minrow-20261023b: minimize is the RIGHTMOST item on the Observe row; the row is padded 44px (32px button + 12px gap) so Observe and the rest shift left */
setInterval(brMinPos,700);window.addEventListener('resize',brMinPos);

/* roboticon-20261023a: Bot Room dock glyph is a small robot (icon only, tooltip via title). Antenna = status light: always flashing; green normally, red while awaiting the owner. Side dot hidden (the antenna replaces it). */
(function(){var st=document.createElement('style');st.textContent='#brBotDock .brAnt{fill:#16c060;animation:brBlink 1s steps(1) infinite}#brBotDock.stopped .brAnt{fill:#e5202b}#brBotDock .brDot{display:none!important}';document.head.appendChild(st);})();
